    private const int MaxDisplayChanges = 50;

    private bool _loading = true;
    private string? _diffError;
    private bool _initialStateFallback;
    private AggregateStateDiff? _diff;
    private AggregateStateSnapshot? _fromState;
    private AggregateStateSnapshot? _toState;
    private string? _fromStateWarning;
    private string? _toStateWarning;
    private List<FieldChange> _displayedChanges = [];
    private bool _showAllChanges;

    private long _previousFrom = -1;
    private long _previousTo = -1;

    [Parameter, EditorRequired]
    public string TenantId { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public string Domain { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public string AggregateId { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public long FromSequence { get; set; }

    [Parameter, EditorRequired]
    public long ToSequence { get; set; }

    [Parameter]
    public EventCallback OnClose { get; set; }

    protected override async Task OnParametersSetAsync()
    {
        if (FromSequence == _previousFrom && ToSequence == _previousTo)
        {
            return;
        }

        _previousFrom = FromSequence;
        _previousTo = ToSequence;
        await LoadDiffAsync();
    }

    private async Task LoadDiffAsync()
    {
        _loading = true;
        _diffError = null;
        _initialStateFallback = false;
        _diff = null;
        _fromState = null;
        _toState = null;
        _fromStateWarning = null;
        _toStateWarning = null;
        _showAllChanges = false;
        StateHasChanged();

        // Use a generous client timeout aligned with the admin service invocation path.
        // The 5s value used previously masked legitimate upstream failures as range errors.
        using CancellationTokenSource cts = new(TimeSpan.FromSeconds(DiffTimeoutSeconds));
        try
        {
            // Launch all 3 calls in parallel but track each independently so a single
            // upstream failure cannot pretend the whole diff range was the problem.
            Task<AggregateStateDiff?> diffTask = ApiClient.GetAggregateStateDiffAsync(
                TenantId, Domain, AggregateId, FromSequence, ToSequence, cts.Token);

            Task<AggregateStateSnapshot?> fromStateTask = FromSequence == 0
                ? Task.FromResult<AggregateStateSnapshot?>(null)
                : ApiClient.GetAggregateStateAtPositionAsync(
                    TenantId, Domain, AggregateId, FromSequence, cts.Token);

            Task<AggregateStateSnapshot?> toStateTask = ApiClient.GetAggregateStateAtPositionAsync(
                TenantId, Domain, AggregateId, ToSequence, cts.Token);

            try
            {
                await Task.WhenAll(diffTask, fromStateTask, toStateTask).ConfigureAwait(false);
            }
            catch
            {
                // Allow per-task classification below; WhenAll surfaces only one exception.
            }

            ClassifyTaskResult(diffTask, "diff", out _diff, out string? diffWarning);
            ClassifyTaskResult(fromStateTask, "fromState", out _fromState, out string? fromStateWarning);
            ClassifyTaskResult(toStateTask, "toState", out _toState, out string? toStateWarning);

            // If the primary diff succeeded, demote auxiliary state failures to side warnings
            // so the diff itself is still rendered.
            if (_diff is not null)
            {
                UpdateDisplayedChanges();

                if (_fromState is null && FromSequence != 0)
                {
                    _fromStateWarning = fromStateWarning ?? $"Full state at #{FromSequence} not available.";
                }

                if (_toState is null)
                {
                    _toStateWarning = toStateWarning ?? $"Full state at #{ToSequence} not available.";
                }

                // Only the diff's own warning (if any) is surfaced as the primary error.
                _diffError = diffWarning;
            }
            else
            {
                // Diff itself missing \u2014 pick the most actionable error across all three tasks.
                _diffError = SelectPrimaryError(diffWarning, fromStateWarning, toStateWarning);

                if (_diffError is null)
                {
                    if (FromSequence == 0 && _toState is not null)
                    {
                        _initialStateFallback = true;
                    }
                    else
                    {
                        _diffError = "State diff not available \u2014 one or both positions have no state.";
                    }
                }
            }
        }
        finally
        {
            _loading = false;
        }
    }

    private const int DiffTimeoutSeconds = 30;

    private void ClassifyTaskResult<T>(Task<T?> task, string tag, out T? value, out string? warning)
        where T : class
    {
        value = null;
        warning = null;

        if (task.IsCanceled)
        {
            warning = "Diff timed out \u2014 try a smaller range.";
            return;
        }

        if (task.IsFaulted)
        {
            Exception inner = task.Exception?.GetBaseException() ?? new InvalidOperationException("Unknown error.");
            warning = inner switch
            {
                UnauthorizedAccessException => "Sign in required to compute the state diff.",
                ForbiddenAccessException => "Access denied. You do not have permission to compute this diff.",
                ServiceUnavailableException => "Backend unavailable. Diff is temporarily offline.",
                OperationCanceledException => "Diff timed out \u2014 try a smaller range.",
                AdminApiProblemException problem => problem.Detail ?? problem.Message,
                InvalidOperationException invalid => string.IsNullOrWhiteSpace(invalid.Message)
                    ? "Invalid sequence range for diff."
                    : invalid.Message,
                HttpRequestException => "State diff request failed. Try again or check the backend health.",
                _ => "Unexpected error while computing the diff.",
            };

            if (inner is not (UnauthorizedAccessException or ForbiddenAccessException or ServiceUnavailableException or OperationCanceledException))
            {
                Logger.LogWarning(
                    inner,
                    "State diff [{Tag}] failure for {TenantId}/{Domain}/{AggregateId} from {From} to {To}.",
                    tag,
                    TenantId,
                    Domain,
                    AggregateId,
                    FromSequence,
                    ToSequence);
            }

            return;
        }

        if (task.IsCompletedSuccessfully)
        {
            value = task.Result;
            return;
        }

        // Defensive: a non-terminal task should not reach here after WhenAll returns,
        // but if it does, do not silently report "no diff" \u2014 surface a diagnostic warning.
        warning = "State diff did not complete in time.";
        Logger.LogWarning(
            "State diff [{Tag}] task in unexpected non-terminal state for {TenantId}/{Domain}/{AggregateId} from {From} to {To}.",
            tag,
            TenantId,
            Domain,
            AggregateId,
            FromSequence,
            ToSequence);
    }

    private static string? SelectPrimaryError(string? a, string? b, string? c)
    {
        // Prefer the most specific error if any task surfaced one.
        foreach (string? candidate in new[] { a, b, c })
        {
            if (!string.IsNullOrEmpty(candidate))
            {
                return candidate;
            }
        }

        return null;
    }

    private void UpdateDisplayedChanges()
    {
        if (_diff is null)
        {
            _displayedChanges = [];
            return;
        }

        _displayedChanges = _showAllChanges || _diff.ChangedFields.Count <= MaxDisplayChanges
            ? _diff.ChangedFields.ToList()
            : _diff.ChangedFields.Take(MaxDisplayChanges).ToList();
    }

    private void ShowAllChanges()
    {
        _showAllChanges = true;
        UpdateDisplayedChanges();
    }

    private async Task HandleClose()
    {
        await OnClose.InvokeAsync().ConfigureAwait(false);
    }

    private static string FormatTimestamp(AggregateStateSnapshot? snapshot) =>
        snapshot?.Timestamp.ToString("yyyy-MM-dd HH:mm:ss zzz") ?? "N/A";

    private static string TruncateValue(string value)
    {
        if (string.IsNullOrEmpty(value))
        {
            return "\u2014";
        }

        return value.Length > 80 ? value[..80] + "\u2026" : value;
    }

    private static RenderFragment FieldValueContent(string? value, AdminRedactedContent? content, string prefix) => builder =>
    {
        if (content is not null)
        {
